package minheap

import "testing"

func TestPushPop(t *testing.T) {
	h := NewMinHeap()
	h.Push(3)
	h.Push(1)
	h.Push(4)
	h.Push(2)
	if got := h.Pop(); got != 1 {
		t.Fatalf("want 1, got %d", got)
	}
	if got := h.Pop(); got != 2 {
		t.Fatalf("want 2, got %d", got)
	}
}

func TestPeek(t *testing.T) {
	h := NewMinHeap()
	h.Push(5)
	h.Push(2)
	h.Push(8)
	if got := h.Peek(); got != 2 {
		t.Fatalf("want 2, got %d", got)
	}
	if h.Len() != 3 {
		t.Fatalf("Peek should not remove element")
	}
}

func TestLen(t *testing.T) {
	h := NewMinHeap()
	if h.Len() != 0 {
		t.Fatal("new heap should have len 0")
	}
	h.Push(1)
	h.Push(2)
	if h.Len() != 2 {
		t.Fatalf("want 2, got %d", h.Len())
	}
}

func TestSortOrder(t *testing.T) {
	h := NewMinHeap()
	values := []int{9, 3, 7, 1, 5}
	for _, v := range values {
		h.Push(v)
	}
	prev := h.Pop()
	for h.Len() > 0 {
		curr := h.Pop()
		if curr < prev {
			t.Fatalf("out of order: %d before %d", prev, curr)
		}
		prev = curr
	}
}

func TestSingleElement(t *testing.T) {
	h := NewMinHeap()
	h.Push(42)
	if got := h.Pop(); got != 42 {
		t.Fatalf("want 42, got %d", got)
	}
	if h.Len() != 0 {
		t.Fatal("heap should be empty after popping last element")
	}
}

task_spec.prompt:
Implement MinHeap in heap.go using container/heap.

package minheap

import "container/heap"

type intHeap []int

func (h intHeap) Len() int           { return len(h) }
func (h intHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h intHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *intHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *intHeap) Pop() any {
    old := *h
    n := len(old)
    x := old[n-1]
    *h = old[:n-1]
    return x
}

type MinHeap struct { h *intHeap }

func NewMinHeap() *MinHeap {
    h := &intHeap{}
    heap.Init(h)
    return &MinHeap{h: h}
}

func (m *MinHeap) Push(v int) { heap.Push(m.h, v) }
func (m *MinHeap) Pop() int   { return heap.Pop(m.h).(int) }
func (m *MinHeap) Peek() int  { return (*m.h)[0] }
func (m *MinHeap) Len() int   { return m.h.Len() }

All 5 tests must pass.
Run: go test ./...
